 * MechRing Controller Trigger Map
 * Maps button combinations to MechMind actions
 * 
 * Button naming convention:
 *   R_ prefix = DriveRing (RIGHT joystick)
 *   L_ prefix = DomeRing (LEFT joystick)
 * 
 * Trigger pattern (v3.0):
 *   LA_Rdir = Left A button + Right direction (up/down/left/right)
 *   LB_Rdir = Left B button + Right direction
 *   LC_Rdir = Left C button + Right direction
 *   LD_Rdir = Left D button + Right direction
 *   RA_Ldir = Right A button + Left direction
 *   RB_Ldir = Right B button + Left direction
 *   RC_Ldir = Right C button + Left direction
 *   RD_Ldir = Right D button + Left direction
 */

// ===== LEFT A + RIGHT DIRECTIONS (Dome Panel Control) =====
triggerMap["LA_Rup"]    = "DomeP1Open";
triggerMap["LA_Rdown"]  = "DomeP1Close";
triggerMap["LA_Rleft"]  = "DomeP2Open";
triggerMap["LA_Rright"] = "DomeP2Close";

// ===== LEFT B + RIGHT DIRECTIONS (More Dome Panels) =====
triggerMap["LB_Rup"]    = "DomeP3Open";
triggerMap["LB_Rdown"]  = "DomeP3Close";
triggerMap["LB_Rleft"]  = "DomeP4Open";
triggerMap["LB_Rright"] = "DomeP4Close";

// ===== LEFT C + RIGHT DIRECTIONS (Body Panel Control) =====
triggerMap["LC_Rup"]    = "BodyP1Open";
triggerMap["LC_Rdown"]  = "BodyP1Close";
triggerMap["LC_Rleft"]  = "BodyP2Open";
triggerMap["LC_Rright"] = "BodyP2Close";

// ===== LEFT D + RIGHT DIRECTIONS (More Body Panels) =====
triggerMap["LD_Rup"]    = "BodyP3Open";
triggerMap["LD_Rdown"]  = "BodyP3Close";
triggerMap["LD_Rleft"]  = "BodyP4Open";
triggerMap["LD_Rright"] = "BodyP4Close";

// ===== RIGHT A + LEFT DIRECTIONS (Holo Control) =====
triggerMap["RA_Lup"]    = "HoloUp";
triggerMap["RA_Ldown"]  = "HoloDown";
triggerMap["RA_Lleft"]  = "HoloLeft";
triggerMap["RA_Lright"] = "HoloRight";

// ===== RIGHT B + LEFT DIRECTIONS (Sound/Volume Control) =====
triggerMap["RB_Lup"]    = "VolumeUp";
triggerMap["RB_Ldown"]  = "VolumeDown";
triggerMap["RB_Lleft"]  = "VolumeMid";
triggerMap["RB_Lright"] = "VolumeMax";

// ===== RIGHT C + LEFT DIRECTIONS (Emotions & Actions) =====
triggerMap["RC_Lup"]    = "Happy";
triggerMap["RC_Ldown"]  = "Sad";
triggerMap["RC_Lleft"]  = "Fear";
triggerMap["RC_Lright"] = "Anger";

// ===== RIGHT D + LEFT DIRECTIONS (Complex Actions) =====
triggerMap["RD_Lup"]    = "Wave";
triggerMap["RD_Ldown"]  = "Scream";
triggerMap["RD_Lleft"]  = "FastSmirk";
triggerMap["RD_Lright"] = "Wave2";
